// The Coin Values table gives each coin's worth in gold pieces: CP 1/100, SP 1/10, EP 1/2, GP 1, PP 10. Here
// everything is counted in copper pieces, so all sums are whole numbers.

export const COINS = ['pp', 'gp', 'ep', 'sp', 'cp'] as const;
export type Coin = (typeof COINS)[number];

/** What each coin is worth in copper pieces (the SRD's value in gold pieces x 100). */
export const COIN_VALUE_CP: Record<Coin, number> = { cp: 1, sp: 10, ep: 50, gp: 100, pp: 1000 };

export const COIN_NAMES: Record<Coin, string> = {
  cp: 'Copper Piece',
  sp: 'Silver Piece',
  ep: 'Electrum Piece',
  gp: 'Gold Piece',
  pp: 'Platinum Piece',
};

/** "A coin weighs about a third of an ounce, so fifty coins weigh a pound." */
export const COINS_PER_POUND = 50;

/** Coins by kind; a missing kind is none. */
export type Purse = Partial<Record<Coin, number>>;

/** A price as the SRD writes it, e.g. 15 GP. */
export interface Price {
  amount: number;
  coin: Coin;
}

/**
 * The coins change is given in. Electrum is a real SRD coin, but nobody expects it as change, so it is left out
 * unless asked for.
 */
export const CHANGE_COINS: readonly Coin[] = ['pp', 'gp', 'sp', 'cp'];

function checkCount(n: number, what: string) {
  if (!Number.isInteger(n) || n < 0) throw new RangeError(`${what} must be a whole number of 0 or more, got ${n}`);
}

export const priceInCopper = ({ amount, coin }: Price): number => {
  if (!(amount >= 0)) throw new RangeError(`A price cannot be negative, got ${amount}`);
  // 1/4 lb. darts cost 5 CP; prices are whole coins, but be safe with fractions of a gold piece
  return Math.round(amount * COIN_VALUE_CP[coin]);
};

/** Everything in the purse, in copper pieces. */
export function totalInCopper(purse: Purse): number {
  return COINS.reduce((sum, coin) => {
    const n = purse[coin] ?? 0;
    checkCount(n, `The number of ${COIN_NAMES[coin]}s`);
    return sum + n * COIN_VALUE_CP[coin];
  }, 0);
}

export function canAfford(purse: Purse, price: Price | number): boolean {
  return totalInCopper(purse) >= (typeof price === 'number' ? price : priceInCopper(price));
}

/** An amount of copper as the fewest coins, e.g. 150 -> 1 GP and 5 SP. */
export function makeChange(copper: number, coins: readonly Coin[] = CHANGE_COINS): Purse {
  checkCount(copper, 'An amount of copper');
  if (!coins.includes('cp')) throw new RangeError('Change needs copper pieces to come out exact');
  const out: Purse = {};
  let left = copper;
  for (const coin of [...coins].sort((a, b) => COIN_VALUE_CP[b] - COIN_VALUE_CP[a])) {
    const n = Math.floor(left / COIN_VALUE_CP[coin]);
    if (n) out[coin] = n;
    left -= n * COIN_VALUE_CP[coin];
  }
  return out;
}

/**
 * Pays a price from a purse: smallest coins first, then change for whatever was overpaid. Returns the purse
 * afterwards, or null when it cannot be afforded. The purse passed in is not changed.
 */
export function pay(purse: Purse, price: Price | number): Purse | null {
  const cost = typeof price === 'number' ? price : priceInCopper(price);
  checkCount(cost, 'A price in copper');
  if (!canAfford(purse, cost)) return null;
  const left: Purse = { ...purse };
  let owed = cost;
  for (const coin of [...COINS].reverse()) {
    if (owed <= 0) break;
    const have = left[coin] ?? 0;
    const use = Math.min(have, Math.ceil(owed / COIN_VALUE_CP[coin]));
    left[coin] = have - use;
    owed -= use * COIN_VALUE_CP[coin];
  }
  // owed is now 0 or negative: a negative amount is change due
  const change = makeChange(-owed);
  for (const coin of COINS) {
    const n = (left[coin] ?? 0) + (change[coin] ?? 0);
    if (n) left[coin] = n;
    else delete left[coin];
  }
  return left;
}

/** "12 GP, 5 SP, 3 CP", largest coin first; an empty purse is "0 GP". */
export function formatPurse(purse: Purse): string {
  const parts = COINS.filter(c => (purse[c] ?? 0) > 0).map(
    c => `${(purse[c] ?? 0).toLocaleString('en')} ${c.toUpperCase()}`,
  );
  return parts.length ? parts.join(', ') : '0 GP';
}
